import type { Move, Pose, Stage } from '../../core/figure'

/** Stage channels of a mocap row, after the 12 pose angles. */
export const COLS = ['lift', 'shift', 'turn', 'roll', 'twist', 'armOut', 'farArmOut', 'foreOut', 'farForeOut', 'legOut', 'farLegOut', 'shinOut', 'farShinOut'] as const satisfies readonly (keyof Stage)[]

/** A row: 12 pose angles, COLS, then `dur` and `hold` in seconds. */
export type Row = number[]

/** A solid Move from rows generated by `npm run mocap` (app/tools/mocap). Cycles travel by the clip's shift. */
export function clip(base: Omit<Move, 'keys' | 'beats' | 'solid'>, rows: Row[]): Move {
  const shift = rows[rows.length - 1][13] - rows[0][13]
  return {
    ...base, solid: true, ms: 1000, ...(base.mode === 'cycle' && shift ? { travel: shift } : {}),
    keys: rows.map((r) => r.slice(0, 12) as Pose),
    beats: rows.map((r) => ({ ...Object.fromEntries(COLS.map((c, j) => [c, r[12 + j]])), dur: r[25], hold: r[26] })),
  }
}
